#!/usr/bin/env node
// 自包含 Brotli 包；完整引擎、元数据及第三方许可证均保留在载荷中。
import { brotliDecompressSync } from "node:zlib";
const source = "const __sdsEntryUrl = " + JSON.stringify(import.meta.url) + ";\n" + brotliDecompressSync(Buffer.from("", "base64")).toString("utf8");
await import("data:text/javascript;base64," + Buffer.from(source).toString("base64"));
